// Bringing a pre-accounts season into the new database.
//
// A backup exported from the localStorage version of Grainflow cannot be
// written as-is, for one unavoidable reason: its ids look like `msoad38fu5po5n`
// — generated by the old uid(), which was a timestamp and some randomness. The
// schema uses uuid columns. Postgres will reject every row.
//
// So every id has to be reissued, and every reference to every id has to follow
// it. That is the whole job here, and it is the part where a mistake is silent:
// a movement whose froms[] still points at a paddock's old id does not error, it
// just quietly detaches from the paddock it came out of. The counts still look
// right. The position still adds up. And the link is gone.
//
// Hence: remap, then verify the remap, then report — before anything is written.

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export const isUuid = (v) => typeof v === 'string' && UUID_RE.test(v);

const newId = () =>
  (globalThis.crypto?.randomUUID
    ? globalThis.crypto.randomUUID()
    // Node before 19 in the CLI validator; never used in the browser.
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
      }));

/**
 * Reissue every id as a UUID and rewrite every reference.
 *
 * Returns the new state plus the map, so the caller can verify rather than
 * trust. Does not mutate the input.
 */
export function remapIds(input) {
  const state = JSON.parse(JSON.stringify(input));
  const map = new Map();

  const idFor = (old) => {
    if (old === null || old === undefined || old === '') return old;
    if (isUuid(old)) return old;              // already migrated, leave alone
    if (!map.has(old)) map.set(old, newId());
    return map.get(old);
  };

  for (const year of Object.values(state.years || {})) {
    for (const c of year.commodities || []) c.id = idFor(c.id);
    for (const f of year.fields || []) f.id = idFor(f.id);
    for (const s of year.storages || []) s.id = idFor(s.id);
    for (const s of year.sales || []) s.id = idFor(s.id);
    for (const m of year.movements || []) m.id = idFor(m.id);
    for (const i of year.invoices || []) i.id = idFor(i.id);
  }

  // Second pass for references, so every target already has its new id.
  for (const year of Object.values(state.years || {})) {
    for (const f of year.fields || []) f.commodityId = idFor(f.commodityId);
    for (const s of year.storages || []) s.commodityId = idFor(s.commodityId);
    for (const s of year.sales || []) s.commodityId = idFor(s.commodityId);

    for (const m of year.movements || []) {
      m.commodityId = idFor(m.commodityId);
      m.correctsId = idFor(m.correctsId);
      for (const leg of m.froms || []) leg.id = idFor(leg.id);
      for (const leg of m.tos || []) leg.id = idFor(leg.id);
    }

    for (const i of year.invoices || []) i.saleId = idFor(i.saleId);
  }

  return { state, map };
}

// ---------------------------------------------------------------------------
// The shape the current app expects
//
// A season saved by an early build does not have the keys a later build reads.
// Overheads arrived after Ben's 2025 season was created, so his years have no
// `overheads` object at all — and views/settings.js reads `overheads.finance`
// straight out, with no guard. The import wrote the season, the settings view
// re-rendered, and the whole thing came back as "Cannot read properties of
// undefined (reading 'finance')".
//
// Nothing here invents data. It adds empty containers and zeroes so that a
// season written before a feature existed opens in a build that has it.
//
// storage.js imports these rather than keeping its own copies, because two
// lists of the same field names in two files is precisely how 'level' and
// 'storage' happened.
// ---------------------------------------------------------------------------

export const DEFAULT_OVERHEADS = {
  finance: 0, equipmentRepayments: 0, depreciation: 0, wages: 0, drawings: 0,
  admin: 0, energy: 0, insurance: 0, repairsMaintenance: 0, other: 0,
};

export const DEFAULT_BUSINESS_DETAILS = {
  entityName: '', abn: '', ngr: '', contactName: '', phone: '', email: '', address: '',
  paymentTermsDays: 14,
  bankName: '', accountName: '', bsb: '', accountNumber: '',
};

const YEAR_LISTS = ['commodities', 'fields', 'sales', 'storages', 'movements', 'invoices'];

/**
 * Fill in anything the current app reads that an older season does not carry.
 *
 * Returns the list of what was added, so the caller can say so out loud rather
 * than silently reshaping someone's records.
 */
export function normalise(input) {
  const state = input;
  const filled = [];

  if (!state.businessDetails) {
    state.businessDetails = { ...DEFAULT_BUSINESS_DETAILS };
    filled.push('business details');
  } else {
    for (const [k, v] of Object.entries(DEFAULT_BUSINESS_DETAILS)) {
      if (state.businessDetails[k] === undefined) state.businessDetails[k] = v;
    }
  }

  for (const [label, year] of Object.entries(state.years || {})) {
    if (!year || typeof year !== 'object') continue;

    for (const key of YEAR_LISTS) {
      if (!Array.isArray(year[key])) {
        year[key] = [];
        filled.push(`${label} ${key}`);
      }
    }

    if (!year.overheads || typeof year.overheads !== 'object') {
      year.overheads = { ...DEFAULT_OVERHEADS };
      filled.push(`${label} overheads`);
    } else {
      for (const [k, v] of Object.entries(DEFAULT_OVERHEADS)) {
        if (year.overheads[k] === undefined) year.overheads[k] = v;
      }
    }
  }

  return { state, filled };
}

// What the database will accept. Kept here rather than imported so the CLI
// validator can run without pulling in anything browser-specific — and
// exported so tests/enums.test.mjs can hold it against the check constraints
// in supabase/migrations and against the literals the app actually writes.
// Twice now a value has been invented here rather than read out of the app
// ('storage' for a silo leg, 'level' for a fill state), and both times the
// failure surfaced as a rejected push, not a failing test.
export const ALLOWED = {
  refType: ['field', 'silo', 'sale'],          // app vocabulary; mapping translates
  direction: ['from', 'to'],
  movementStatus: ['open', 'closed'],
  weightStatus: ['estimate', 'final'],
  storageKind: ['silo', 'bunker', 'tally'],    // tally = counted bales, not tonnes
  fillState: ['peak', 'flat', 'decline'],      // three surfaces, three volume formulas
  yieldMode: ['estimate', 'actual'],
  invoiceStatus: ['outstanding', 'paid'],
};

/**
 * Check a season against everything the database will enforce, and report all
 * of it at once rather than stopping at the first problem — a list of twelve
 * issues is one afternoon, twelve rounds of one issue is a week.
 */
export function validate(state) {
  const problems = [];
  const warnings = [];
  const stats = {
    seasons: 0, commodities: 0, paddocks: 0, storages: 0,
    sales: 0, movements: 0, legs: 0, invoices: 0, photos: 0, photoBytes: 0,
  };

  const problem = (where, msg) => problems.push(`${where}: ${msg}`);
  const warn = (where, msg) => warnings.push(`${where}: ${msg}`);

  const seenIds = new Set();
  const checkId = (where, id) => {
    if (!id) return problem(where, 'missing id');
    if (!isUuid(id)) return problem(where, `id "${id}" is not a UUID`);
    if (seenIds.has(id)) problem(where, `duplicate id ${id}`);
    seenIds.add(id);
  };

  const oneOf = (where, field, value, allowed) => {
    if (value === undefined || value === null || value === '') return;
    if (!allowed.includes(value)) {
      problem(where, `${field} is "${value}" — must be one of ${allowed.join(', ')}`);
    }
  };

  const ticketNos = new Map();

  for (const [label, year] of Object.entries(state.years || {})) {
    stats.seasons += 1;
    const ids = {
      commodity: new Set((year.commodities || []).map((c) => c.id)),
      field: new Set((year.fields || []).map((f) => f.id)),
      storage: new Set((year.storages || []).map((s) => s.id)),
      sale: new Set((year.sales || []).map((s) => s.id)),
    };

    for (const c of year.commodities || []) {
      stats.commodities += 1;
      checkId(`${label} commodity "${c.name || '?'}"`, c.id);
      if (!c.name) warn(`${label} commodity`, 'has no name');
    }

    for (const f of year.fields || []) {
      stats.paddocks += 1;
      const w = `${label} paddock "${f.name || '?'}"`;
      checkId(w, f.id);
      oneOf(w, 'yieldMode', f.yieldMode, ALLOWED.yieldMode);
      if (f.commodityId && !ids.commodity.has(f.commodityId)) {
        problem(w, 'points at a commodity that is not in this season');
      }
    }

    for (const s of year.storages || []) {
      stats.storages += 1;
      const w = `${label} storage "${s.name || '?'}"`;
      checkId(w, s.id);
      oneOf(w, 'kind', s.kind, ALLOWED.storageKind);
      oneOf(w, 'fillState', s.fillState, ALLOWED.fillState);
      if (s.commodityId && !ids.commodity.has(s.commodityId)) {
        problem(w, 'points at a commodity that is not in this season');
      }
    }

    for (const s of year.sales || []) {
      stats.sales += 1;
      const w = `${label} sale ${s.contractNo || s.buyer || '?'}`;
      checkId(w, s.id);
      if (s.commodityId && !ids.commodity.has(s.commodityId)) {
        problem(w, 'points at a commodity that is not in this season');
      }
    }

    for (const m of year.movements || []) {
      stats.movements += 1;
      const w = `${label} ticket ${m.ticketNo ?? '(unnumbered)'}`;
      checkId(w, m.id);
      oneOf(w, 'status', m.status, ALLOWED.movementStatus);
      oneOf(w, 'weightStatus', m.weightStatus, ALLOWED.weightStatus);

      if (m.ticketNo !== undefined && m.ticketNo !== null) {
        if (ticketNos.has(m.ticketNo)) {
          problem(w, `ticket number ${m.ticketNo} is used twice — the database enforces one per farm`);
        }
        ticketNos.set(m.ticketNo, true);
      }

      if (m.photoDataUrl) {
        stats.photos += 1;
        stats.photoBytes += m.photoDataUrl.length;
      }

      for (const [dir, legs] of [['from', m.froms], ['to', m.tos]]) {
        for (const leg of legs || []) {
          stats.legs += 1;
          oneOf(w, `${dir} type`, leg.type, ALLOWED.refType);
          if (!leg.id) { warn(w, `a ${dir} leg has no target`); continue; }
          const pool = { field: ids.field, silo: ids.storage, sale: ids.sale }[leg.type];
          if (pool && !pool.has(leg.id)) {
            problem(w, `${dir} leg points at a ${leg.type} that is not in this season`);
          }
        }
      }
    }

    for (const i of year.invoices || []) {
      stats.invoices += 1;
      const w = `${label} invoice ${i.invoiceNo ?? '?'}`;
      checkId(w, i.id);
      oneOf(w, 'status', i.status, ALLOWED.invoiceStatus);
      if (i.saleId && !ids.sale.has(i.saleId)) {
        problem(w, 'points at a sale that is not in this season');
      }
    }
  }

  if (!state.currentYear || !state.years?.[state.currentYear]) {
    problem('season', 'currentYear does not name a season that exists');
  }

  return { ok: problems.length === 0, problems, warnings, stats };
}

/**
 * The whole import path: reissue ids, then check. Never writes.
 */
export function prepareImport(rawJson) {
  const parsed = typeof rawJson === 'string' ? JSON.parse(rawJson) : rawJson;
  const before = validate(parsed);
  const { state, map } = remapIds(parsed);

  // Shape before values: validate() walks year.movements and year.invoices, so
  // a season that predates those keys has to gain them first.
  const { filled } = normalise(state);

  const after = validate(state);
  return {
    state,
    remapped: map.size,
    filled,
    before,
    after,
  };
}
